    public string analysis_identity(GodotObject actor){using var edits=new AudioEditSessionOperations();return edits.silence_source_identity(actor);}
    public bool analysis_provenance_current(Control o,Settings data,long generation)
    {
        string id=Get(data,"clip_id","").AsString();var actor=Document(o).Call("actor_for_clip",id).AsGodotObject();var clip=Session(o).Call("primary_clip").AsGodotObject();long revision=Session(o).Get("revision").AsInt64();string identity=Get(data,"source_identity","").AsString();return generation==revision&&Get(data,"revision",-1).AsInt64()==revision&&Get(data,"owner_id",0).AsInt64()==unchecked((long)Session(o).GetInstanceId())&&Get(data,"document_id",0).AsInt64()==unchecked((long)Document(o).GetInstanceId())&&Session(o).Get("_before").VariantType==Variant.Type.Nil&&clip!=null&&clip.Get("id").AsString()==id&&actor!=null&&identity.Length>0&&identity==analysis_identity(actor);
    }
    public bool analysis_current(Control o){var result=Dict(o,"_analysis_result");return analysis_provenance_current(o,result,Get(result,"revision",-1).AsInt64());}
    private static void ShowAnalysis(Control o){var bottom=Field<TabContainer>(o,"bottom");bottom.Visible=true;bottom.CurrentTab=5;}
    public void analyze_clip(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Stop recording before analyzing dialogue.");return;}var actor=Session(o).Call("primary_actor").AsGodotObject();if(actor==null)return;o.Call("_close_silence_review");var source=Get(Dict(actor,"values"),"audio");using var analysis=new AudioAnalysisOperations();string problem=analysis.silence_source_error(source);if(problem.Length>0){notice(o,problem);return;}string identity=analysis_identity(actor);if(source.VariantType==Variant.Type.String)GD.Load<CSharpScript>("res://scripts/actors/core/ActorAudio.cs").Call("invalidate",source);var clip=Session(o).Call("primary_clip").AsGodotObject();string id=clip.Get("id").AsString();double start=clip.Get("source_offset").AsDouble(),seconds=clip.Get("duration").AsDouble()*clip.Get("playback_speed").AsDouble();if(Get(Dict(actor,"values"),"loop",false).AsBool()){start=0;seconds=-1;}if(identity.Length==0||identity!=analysis_identity(actor)){notice(o,"The source changed while opening it. Analyze again.");return;}long ownerId=unchecked((long)Session(o).GetInstanceId()),documentId=unchecked((long)Document(o).GetInstanceId()),revision=Session(o).Get("revision").AsInt64();double threshold=o.Get("_silence_threshold").AsDouble(),minimum=o.Get("_silence_minimum").AsDouble();Work(o,"analysis",revision,job=>{using var worker=new AudioAnalysisOperations();var result=worker.analyze_source(source,threshold,minimum,job,start,seconds);result["analysis_method"]=Get(result,"method","Analysis").AsString();result["clip_id"]=id;result["source_identity"]=identity;result["owner_id"]=ownerId;result["document_id"]=documentId;result["revision"]=revision;result["threshold"]=threshold;result["minimum"]=minimum;return result;});ShowAnalysis(o);
    }
    public void measure_loudness(Control o)
    {
        var actor=Session(o).Call("primary_actor").AsGodotObject();if(actor==null)return;var source=Get(Dict(actor,"values"),"audio");string identity=analysis_identity(actor),id=Session(o).Call("primary_clip").AsGodotObject().Get("id").AsString();long ownerId=unchecked((long)Session(o).GetInstanceId()),documentId=unchecked((long)Document(o).GetInstanceId()),revision=Session(o).Get("revision").AsInt64();Work(o,"loudness",revision,job=>{using var analysis=new AudioAnalysisOperations();var result=analysis.loudness(source,job);result["source_identity"]=identity;result["clip_id"]=id;result["owner_id"]=ownerId;result["document_id"]=documentId;result["revision"]=revision;return result;});ShowAnalysis(o);
    }
    public void add_attack_markers(Control o)
    {
        if(!analysis_current(o)){Field<Label>(o,"status").Text="The analyzed source changed. Analyze it again.";return;}var result=Dict(o,"_analysis_result");string id=result["clip_id"].AsString();var clip=Document(o).Call("clip_for_id",id).AsGodotObject();var actor=Document(o).Call("actor_for_clip",id).AsGodotObject();double sourceLength=Get(result,"duration",0).AsDouble(),offset=clip.Get("source_offset").AsDouble(),duration=clip.Get("duration").AsDouble(),speed=clip.Get("playback_speed").AsDouble(),end=offset+duration*speed;bool looping=Get(Dict(actor,"values"),"loop",false).AsBool(),reverse=Get(Dict(actor,"values"),"reverse",false).AsBool();var times=new GArray();foreach(var raw in Get(result,"transients",new GArray()).AsGodotArray()){double time=raw.AsDouble();long first=looping&&sourceLength>0?(long)Math.Ceiling((offset-time)/sourceLength):0,last=looping&&sourceLength>0?(long)Math.Floor((end-time)/sourceLength):0;if(last-first>4096){notice(o,"Too many looped markers. Select a shorter clip.");return;}for(long cycle=first;cycle<=last;cycle++){double occurrence=time+cycle*sourceLength;if(occurrence<offset||occurrence>=end)continue;double local=(occurrence-offset)/speed;if(reverse)local=duration-local;times.Add(clip.Get("start_time").AsDouble()+local);if(times.Count>4096){notice(o,"Too many markers. Select a shorter clip.");return;}}}SessionAction(o,"Add transient markers",()=>{foreach(var time in times)Items(Document(o),"markers").Add(new Settings{["id"]=NewAudioId(),["time"]=time,["name"]="Attack"});});
    }
    public string alignment_problem(Control o,GArray ids)
    {
        if(ids.Count!=2)return "Select two clips. The second will be aligned to the first.";foreach(var id in ids){var clip=Document(o).Call("clip_for_id",id.AsString()).AsGodotObject();var actor=Document(o).Call("actor_for_clip",id.AsString()).AsGodotObject();if(clip==null||actor==null)return "An alignment source is no longer available.";if(clip.Get("duration").AsDouble()>300)return "Split clips longer than five minutes before processed alignment.";}return smart_track_problem(o,Get(Document(o).Call("track_for_clip",ids[1].AsString()).AsGodotDictionary(),"id","").AsString());
    }
    public void align_selected(Control o)
    {
        var ids=Items(Session(o),"selected_ids").Duplicate();string problem=alignment_problem(o,ids);if(problem.Length>0){notice(o,problem);return;}if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Finish recording before processed alignment.");return;}long ownerId=unchecked((long)Session(o).GetInstanceId());var snapshot=Document(o).Call("snapshot").As<RefCounted>();var first=snapshot.Call("clip_for_id",ids[0]).AsGodotObject();var second=snapshot.Call("clip_for_id",ids[1]).AsGodotObject();string secondId=second.Get("id").AsString();double start=first.Get("start_time").AsDouble();Work(o,"alignment",Session(o).Get("revision").AsInt64(),job=>{using var analysis=new AudioProcessedAnalysisOperations();var result=analysis.alignment(snapshot,ids,job);result["clip_id"]=secondId;result["base"]=start;result["ids"]=ids;result["owner_id"]=ownerId;return result;});
    }
    public void match_levels(Control o)
    {
        if(Field<Node>(o,"recorder").Get("recording").AsBool()||o.Get("_record_busy").AsBool()){notice(o,"Finish recording before processed RMS matching.");return;}finish_control_edits(o);Session(o).Call("commit");var ids=Items(Session(o),"selected_ids").Duplicate();long ownerId=unchecked((long)Session(o).GetInstanceId());foreach(var id in ids){string problem=smart_track_problem(o,Get(Document(o).Call("track_for_clip",id).AsGodotDictionary(),"id","").AsString());if(problem.Length>0){notice(o,problem);return;}var actor=Document(o).Call("actor_for_clip",id).AsGodotObject();if(Get(Get(Dict(actor,"values"),"automation",new Settings()).AsGodotDictionary(),"volume_db",new GArray()).AsGodotArray().Count>0){notice(o,"Render or remove clip gain automation before matching its base gain.");return;}}if(ids.Count==0)return;var snapshot=Document(o).Call("snapshot").As<RefCounted>();Work(o,"match_levels",Session(o).Get("revision").AsInt64(),job=>{var clips=new GArray();var cache=new Settings();using var mutex=new Godot.Mutex();using var processed=new AudioProcessedAnalysisOperations();foreach(var id in ids){var analysis=processed.rms(snapshot,id.AsString(),job,cache,mutex);string error=Get(analysis,"error","").AsString();if(error.Length>0)return new Settings{["error"]=error};clips.Add(new Settings{["id"]=id,["db"]=Get(analysis,"rms_db",-120).AsDouble(),["base_db"]=Get(Dict(snapshot.Call("actor_for_clip",id).AsGodotObject(),"values"),"volume_db",0).AsDouble()});}return new Settings{["clips"]=clips,["owner_id"]=ownerId,["processed"]=true};});Field<Label>(o,"status").Text="Matching isolated processed clips to -20 dBFS RMS, including routing/effects (up to five minutes each). Nonlinear chains may require remeasurement.";
    }
    public void sample_noise_profile(Control o)
    {
        var waveform=Field<Control>(o,"waveform");var stream=waveform.Get("stream").As<AudioStream>();var selection=waveform.Get("selection").AsVector2I();if(stream==null||selection.Y<=selection.X){notice(o,"Open a waveform and select a short noise-only region without speech or music, then choose Sample Noise.");return;}string id=o.Get("_wave_clip_id").AsString();if(!Session(o).Call("can_edit",id).AsBool())return;double rate=waveform.Get("rate").AsDouble(),start=selection.X/rate,seconds=(selection.Y-selection.X)/rate;Work(o,"noise_profile",Session(o).Get("revision").AsInt64(),job=>{using var analysis=new AudioAnalysisOperations();var result=analysis.noise_profile(stream,start,seconds,job);result["clip_id"]=id;return result;});
    }
